DO $$
DECLARE org bigint; un bigint; oc bigint; oid bigint; tid bigint; other_tid bigint; mid uuid; source jsonb; resolved jsonb; claim jsonb;
 actor uuid; reissued uuid; replay_message public.email_messages; old_fingerprint text; row jsonb; att uuid; lease uuid;
BEGIN
 PERFORM set_config('festapp.email_wake','scheduled',true);
 PERFORM assert_true(public.ticket_wallet_enabled('{}'),'default on');
 PERFORM assert_true(NOT public.ticket_wallet_enabled('{"wallet_enabled":false}'),'explicit false');
 BEGIN PERFORM public.ticket_wallet_enabled('{"wallet_enabled":null}');RAISE EXCEPTION 'accepted null';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM assert_eq(public.merge_ticket_layout_features('[{"code":"ticket","is_enabled":true,"wallet_enabled":false}]','[{"code":"ticket","is_enabled":true}]')->0->>'wallet_enabled','false','old clients retain false');
 PERFORM public.validate_ticket_wallet_appearance('{"wallet_appearance":{"background_color":"#216acf","logo":null}}');
 BEGIN PERFORM public.validate_ticket_wallet_appearance('{"wallet_appearance":{"logo":"https://external.invalid/logo.png"}}');RAISE EXCEPTION 'external image accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM assert_eq(public.merge_ticket_layout_features('[{"code":"ticket","wallet_appearance":{"logo":null}}]','[{"code":"ticket"}]')->0#>>'{wallet_appearance,logo}',NULL::text,'appearance preserved for older clients');
 PERFORM assert_true(NOT has_function_privilege('anon','public.resolve_ticket_wallet(text,text)','EXECUTE'),'no public ticket-id RPC');
 PERFORM assert_true(NOT has_table_privilege('authenticated','eshop.ticket_wallet_capabilities','SELECT'),'RLS private');
 INSERT INTO public.organizations(title,data) VALUES('Wallet test','{"APP_NAME":"Ukázkový portál","DEFAULT_URL":"https://tenant.invalid","WALLET_LOGO_URL":"https://img.festapp.net/assets/test-logo.png"}') RETURNING id INTO org;
 INSERT INTO public.units(title,organization) VALUES('Pořadatel',org) RETURNING id INTO un;
 INSERT INTO public.occasions(title,organization,unit,link,start_time,end_time,features)
 VALUES('Večer hudby',org,un,gen_random_uuid()::text,now()+interval '1 day',now()+interval '2 days','[{"code":"ticket","is_enabled":true}]') RETURNING id INTO oc;
 INSERT INTO eshop.ticket_wallet_integrations(organization,issuer,environment,publishing_ready,web_origin) VALUES(org,'1234','disposable',true,'https://tenant.invalid');
 INSERT INTO eshop.orders(occasion,order_symbol,order_sequence,state,data,price,currency_code)
 VALUES(oc,public.generate_order_symbol(),public.next_order_sequence(oc),'paid','{"email":"guest@example.invalid"}',0,'CZK') RETURNING id INTO oid;
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','WALLET-EXACT-QR') RETURNING id INTO tid;
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','OTHER-QR') RETURNING id INTO other_tid;
 INSERT INTO eshop.order_product_ticket("order",ticket) VALUES(oid,tid);
 PERFORM public.enqueue_paid_order_tickets(oid);
 SELECT message_id INTO STRICT mid FROM public.email_messages WHERE order_id=oid AND message_kind='order_tickets';
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 source:=public.prepare_ticket_wallet(mid,tid,repeat('a',64),'{"v":"1","ciphertext":"sealed"}');
 PERFORM assert_eq(source#>>'{source,tokenHash}',repeat('a',64),'issued source');
 PERFORM assert_eq(public.prepare_ticket_wallet(mid,tid,repeat('b',64),'{"other":true}')#>>'{source,tokenHash}',repeat('a',64),'replay retains original');
 BEGIN PERFORM public.prepare_ticket_wallet(mid,other_tid);RAISE EXCEPTION 'cross ticket allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 resolved:=public.resolve_ticket_wallet(repeat('a',64),repeat('f',64));
 PERFORM assert_eq(resolved#>>'{projection,branding,APP_NAME}','Ukázkový portál','Wallet brand is scoped to the stored organization');
 PERFORM assert_eq(resolved#>>'{projection,branding,WALLET_LOGO_URL}','https://img.festapp.net/assets/test-logo.png','Wallet logo is configured independently of the event');
 PERFORM assert_eq(resolved#>>'{projection,ticket,ticket_symbol}','WALLET-EXACT-QR','exact QR');
 PERFORM assert_true(NOT resolved::text LIKE '%guest@example.invalid%','no customer email');
 PERFORM assert_true(public.resolve_ticket_wallet(repeat('b',64),repeat('f',64)) IS NULL,'unguessable hash');
 claim:=public.claim_ticket_wallet(tid,'1234.object','1234.class');
 PERFORM assert_eq(claim->>'kind','class','class has its own first lease');
 PERFORM assert_true(public.claim_ticket_wallet(tid) IS NULL,'object waits for approved class');
 PERFORM assert_true(NOT public.finish_ticket_wallet(tid,gen_random_uuid(),true),'stale finish fenced');
 PERFORM public.finish_ticket_wallet(tid,(claim->>'lease')::uuid,true);
 claim:=public.claim_ticket_wallet(tid);
 PERFORM assert_eq(claim->>'kind','object','registered object after class');
 PERFORM assert_true(public.claim_ticket_wallet(tid) IS NULL,'concurrent claim blocked');
 PERFORM public.scanner_admit_ticket_internal(tid);
 PERFORM assert_true(public.finish_ticket_wallet(tid,(claim->>'lease')::uuid,true),'captured version completed');
 PERFORM assert_true((SELECT requested>applied FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid),'scan during I/O stays dirty');
 claim:=public.claim_ticket_wallet(tid);
 PERFORM assert_eq(claim#>>'{projection,state}','COMPLETED','next claim sees actual scanned state');
 PERFORM public.finish_ticket_wallet(tid,(claim->>'lease')::uuid,true);
 UPDATE eshop.tickets SET state='used' WHERE id=tid;
 PERFORM assert_eq(public.ticket_wallet_projection_internal(tid)->>'state','COMPLETED','used state');
 UPDATE eshop.tickets SET state='storno' WHERE id=tid;
 PERFORM assert_eq(public.ticket_wallet_projection_internal(tid)->>'state','INACTIVE','storno state');
 UPDATE eshop.tickets SET state='paid' WHERE id=tid;
 UPDATE public.occasions SET end_time=now()-interval '1 hour' WHERE id=oc;
 PERFORM assert_eq(public.ticket_wallet_projection_internal(tid)->>'state','EXPIRED','event ended');
 UPDATE public.occasions SET end_time=now()+interval '20 days',data=jsonb_build_object('place_name','Nový sál') WHERE id=oc;
 PERFORM public.refresh_ticket_wallet_term_internal(tid);
 PERFORM assert_true((SELECT expires_at>now()+interval '26 days' FROM eshop.ticket_wallet_capabilities WHERE ticket_id=tid),'reschedule updates token term');
 PERFORM assert_eq(public.ticket_wallet_projection_internal(tid)#>>'{occasion,data,place_name}','Nový sál','venue sync projection');
 -- The preference affects only future offers; existing capability remains valid.
 UPDATE public.occasions SET features='[{"code":"ticket","is_enabled":true,"wallet_enabled":false}]' WHERE id=oc;
 PERFORM assert_true(public.prepare_ticket_wallet(mid,tid) IS NULL,'disabled offer');
 PERFORM assert_eq(public.resolve_ticket_wallet(repeat('a',64),repeat('f',64))#>>'{projection,state}','ACTIVE','existing link survives preference');
 -- A prepared snapshot is invalidated before send, inside the original queue.
 UPDATE public.email_messages SET workflow_state='cancelled' WHERE message_id<>mid;
 UPDATE public.email_capacity SET paused=false,quota_at=now(),max_rate=100,daily_quota=10000,provider_sent_24h=0,next_send_at=now(),circuit_until=NULL,shared_account=false;
 UPDATE public.email_messages SET workflow_state='pending',target_time=now() WHERE message_id=mid;
 row:=public.claim_email();att:=(row->>'attempt_id')::uuid;lease:=(row->>'lease_token')::uuid;
 PERFORM public.prepare_email(mid,lease,'{"sealed":"snapshot"}',jsonb_build_object('wallet_fingerprint',public.ticket_wallet_fingerprint(oc)));
 UPDATE public.occasions SET features='[{"code":"ticket","is_enabled":true,"wallet_enabled":true}]' WHERE id=oc;
 PERFORM assert_eq(public.begin_email_send(att,lease)->>'disposition','deferred','ON change rerenders unsent snapshot');
 PERFORM assert_true((SELECT prepared IS NULL FROM public.email_messages WHERE message_id=mid),'snapshot discarded');
 row:=public.claim_email();att:=(row->>'attempt_id')::uuid;lease:=(row->>'lease_token')::uuid;
 PERFORM public.prepare_email(mid,lease,'{"sealed":"on-snapshot"}',jsonb_build_object('wallet_fingerprint',public.ticket_wallet_fingerprint(oc)));
 UPDATE public.occasions SET features='[{"code":"ticket","is_enabled":true,"wallet_enabled":false}]' WHERE id=oc;
 PERFORM assert_eq(public.begin_email_send(att,lease)->>'disposition','deferred','OFF change rerenders unsent snapshot');
 row:=public.claim_email();att:=(row->>'attempt_id')::uuid;lease:=(row->>'lease_token')::uuid;
 PERFORM public.prepare_email(mid,lease,'{"sealed":"off-snapshot"}',jsonb_build_object('wallet_fingerprint',public.ticket_wallet_fingerprint(oc)));
 UPDATE public.email_capacity SET paused=true;
 PERFORM assert_eq(public.begin_email_send(att,lease)->>'disposition','deferred','unchanged preference defers only for capacity');
 PERFORM assert_eq((SELECT prepared->>'sealed' FROM public.email_messages WHERE message_id=mid),'off-snapshot','retry retains unchanged snapshot');
 UPDATE public.occasions SET features='[{"code":"ticket","is_enabled":true}]' WHERE id=oc;
 -- Security revocation is permanent until explicit authorized reissue, and no client can manage another tenant.
 UPDATE eshop.ticket_wallet_capabilities SET revoked_at=now() WHERE ticket_id=tid;
 PERFORM assert_true(public.resolve_ticket_wallet(repeat('a',64),repeat('f',64)) IS NULL,'revoked resolver');
 PERFORM assert_true(public.prepare_ticket_wallet(mid,tid,repeat('c',64),'{}') IS NULL,'replay cannot revive');
 PERFORM assert_eq(public.ticket_wallet_projection_internal(tid)->>'state','INACTIVE','revoke sync');
 BEGIN PERFORM public.manage_ticket_wallet(tid,'reissue');RAISE EXCEPTION 'anonymous support accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 actor:=gen_random_uuid();
 INSERT INTO auth.users(id,email) VALUES(actor,actor||'@wallet.invalid');
 INSERT INTO public.user_info(id,organization,name) VALUES(actor,org,'Podpora Wallet');
 INSERT INTO public.occasion_users(occasion,"user",is_editor_order) VALUES(oc,actor,true);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 PERFORM set_config('request.jwt.claim.role','authenticated',true);
 PERFORM public.manage_ticket_wallet(tid,'reissue');
 PERFORM assert_true((SELECT requested>applied FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid),'support operation enqueues existing object');
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 PERFORM assert_true(public.prepare_ticket_wallet(mid,tid,repeat('c',64),'{}') IS NULL,'old intent cannot redeem support reissue');
 reissued:=(public.enqueue_email('order_tickets',jsonb_build_object('organization',org,'occasion',oc,'unit',un),
 'manual-recipient@example.invalid','{"manual":true}','wallet-explicit-reissue','TICKET_ORDER_PAYMENT_DONE',now(),NULL,oid,
 (SELECT email_payment_version FROM eshop.orders WHERE id=oid))->>'message_id')::uuid;
 UPDATE public.email_messages SET created_at=clock_timestamp()+interval '1 millisecond' WHERE message_id=reissued;
 PERFORM assert_true(public.prepare_ticket_wallet(reissued,tid,repeat('a',64),'{}') IS NULL,'reissue cannot reuse a historical token');
 source:=public.prepare_ticket_wallet(reissued,tid,repeat('c',64),'{"v":"1","ciphertext":"new-source"}');
 PERFORM assert_eq(source#>>'{source,tokenHash}',repeat('c',64),'authorized fresh manual intent reissues');
 PERFORM assert_true(public.resolve_ticket_wallet(repeat('a',64),repeat('f',64)) IS NULL,'old generation stays invalid');
 PERFORM assert_eq(public.resolve_ticket_wallet(repeat('c',64),repeat('e',64))#>>'{projection,state}','ACTIVE','new generation valid');
 PERFORM assert_true(EXISTS(SELECT 1 FROM eshop.ticket_wallet_audit a WHERE a.ticket_id=tid AND a.actor=auth.uid() AND action='reissue'),'support audit retained');
 UPDATE eshop.orders SET state='storno' WHERE id=oid;
 PERFORM assert_eq(public.ticket_wallet_projection_internal(tid)->>'state','INACTIVE','order invalidation');
 UPDATE eshop.orders SET state='paid' WHERE id=oid;
 UPDATE eshop.ticket_wallet_capabilities SET expires_at=now()-interval '1 second' WHERE ticket_id=tid;
 PERFORM assert_true(public.resolve_ticket_wallet(repeat('c',64),repeat('e',64)) IS NULL,'explicit expiry cannot replay');
 DELETE FROM eshop.order_product_ticket WHERE ticket=tid;
 DELETE FROM eshop.tickets WHERE id=tid;
 PERFORM assert_true(EXISTS(SELECT 1 FROM eshop.ticket_wallet_objects WHERE ticket_id=tid),'deleted ticket retains provider identity');
 PERFORM assert_eq(public.ticket_wallet_projection_internal(tid)->>'state','INACTIVE','deleted projection');
 RAISE NOTICE 'PASS ticket wallet capability, preference, projection, leases and send fencing';
END $$;

DO $$
DECLARE org bigint; un bigint; oc bigint; oid bigint; other_order bigint; a bigint; b bigint; foreign_ticket bigint; later_ticket bigint;
 mid uuid; other_mid uuid; h1 text:=encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex');
 h2 text:=encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'); hg text:=encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex');
 hf text:=encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'); src text:=encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex');
 context jsonb; scope jsonb; old_revision text; fingerprint text;
BEGIN
 PERFORM set_config('festapp.email_wake','scheduled',true);
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 PERFORM assert_true(NOT has_table_privilege('authenticated','eshop.ticket_wallet_collections','SELECT'),'collection sources private');
 PERFORM assert_true(NOT has_function_privilege('anon','public.get_ticket_wallet_projections(text,bigint[],text)','EXECUTE'),'no public ticket-id collection lookup');
 INSERT INTO public.organizations(title) VALUES('Pořadatel společných vstupenek') RETURNING id INTO org;
 INSERT INTO public.units(title,organization) VALUES('Společenské akce',org) RETURNING id INTO un;
 INSERT INTO public.occasions(title,organization,unit,link,start_time,end_time,features)
 VALUES('Ples pod hvězdami',org,un,gen_random_uuid()::text,now()+interval '1 day',now()+interval '2 days','[{"code":"ticket","is_enabled":true}]') RETURNING id INTO oc;
 INSERT INTO eshop.ticket_wallet_integrations(organization,issuer,environment,publishing_ready,web_origin) VALUES(org,'1234','collections-disposable',true,'https://tenant.invalid');
 INSERT INTO eshop.orders(occasion,order_symbol,order_sequence,state,data,price,currency_code)
 VALUES(oc,public.generate_order_symbol(),public.next_order_sequence(oc),'paid','{"email":"guest@example.invalid"}',0,'CZK') RETURNING id INTO oid;
 INSERT INTO eshop.orders(occasion,order_symbol,order_sequence,state,data,price,currency_code)
 VALUES(oc,public.generate_order_symbol(),public.next_order_sequence(oc),'paid','{"email":"guest@example.invalid"}',0,'CZK') RETURNING id INTO other_order;
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','COLLECTION-ONE') RETURNING id INTO a;
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','COLLECTION-TWO') RETURNING id INTO b;
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','OTHER-ORDER') RETURNING id INTO foreign_ticket;
 INSERT INTO eshop.order_product_ticket("order",ticket) VALUES(oid,a),(oid,b),(other_order,foreign_ticket);
 PERFORM public.enqueue_paid_order_tickets(oid);PERFORM public.enqueue_paid_order_tickets(other_order);
 SELECT message_id INTO STRICT mid FROM public.email_messages WHERE order_id=oid AND message_kind='order_tickets';
 SELECT message_id INTO STRICT other_mid FROM public.email_messages WHERE order_id=other_order AND message_kind='order_tickets';
 PERFORM public.prepare_ticket_wallet(mid,a,h1,'{"sealed":"one"}');PERFORM public.prepare_ticket_wallet(mid,b,h2,'{"sealed":"two"}');
 PERFORM public.prepare_ticket_wallet(other_mid,foreign_ticket,hf,'{"sealed":"foreign"}');
 PERFORM assert_true(public.prepare_ticket_wallet_collection(mid,ARRAY[a,b],hg,'{"sealed":"all"}') IS NULL,'batch not enabled by shared migration');
 fingerprint:=public.ticket_wallet_fingerprint(oc);
 UPDATE eshop.ticket_wallet_integrations SET collection_enabled=true WHERE organization=org;
 PERFORM assert_true(public.ticket_wallet_fingerprint(oc) IS DISTINCT FROM fingerprint,'batch readiness fences unsent snapshots');
 BEGIN PERFORM public.prepare_ticket_wallet_collection(mid,ARRAY[a,foreign_ticket],hg,'{"sealed":"all"}');RAISE EXCEPTION 'cross-order collection allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 context:=public.prepare_ticket_wallet_collection(mid,ARRAY[b,a],hg,'{"sealed":"all"}');
 PERFORM assert_eq(context#>>'{source,tokenHash}',hg,'dedicated collection source created');
 PERFORM assert_eq(public.prepare_ticket_wallet_collection(mid,ARRAY[a,b],repeat('c',64),'{"other":true}')#>>'{source,tokenHash}',hg,'same frozen membership keeps source on resend');
 scope:=public.resolve_ticket_wallet(h1,src);
 PERFORM assert_eq(scope->>'kind','ticket','forwarded individual source stays individual');
 PERFORM assert_eq(jsonb_array_length(scope->'tickets')::text,'1','individual source never expands its order');
 scope:=public.resolve_ticket_wallet(hg,src);old_revision:=scope->>'revision';
 PERFORM assert_eq(scope->>'ticketCount','2','collection includes both authorized tickets');
 PERFORM assert_true(NOT scope::text LIKE '%guest@example.invalid%','collection resolution omits recipient');
 PERFORM assert_eq(jsonb_array_length(public.get_ticket_wallet_projections(hg,ARRAY[a,b],old_revision))::text,'2','part loads exact authorized QR projections');
 PERFORM assert_true(public.get_ticket_wallet_projections(hg,ARRAY[foreign_ticket],old_revision) IS NULL,'cannot inject another order ticket into part');
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','ADDED-LATER') RETURNING id INTO later_ticket;
 INSERT INTO eshop.order_product_ticket("order",ticket) VALUES(oid,later_ticket);
 PERFORM assert_eq(public.resolve_ticket_wallet(hg,src)->>'originalCount','2','old collection does not acquire later order tickets');
 UPDATE eshop.ticket_wallet_capabilities SET revoked_at=now() WHERE ticket_id=a;
 scope:=public.resolve_ticket_wallet(hg,src);
 PERFORM assert_eq(scope->>'ticketCount','1','revoked member cannot be issued');
 PERFORM assert_eq(scope->>'originalCount','2','partial availability stays explicit');
 PERFORM assert_true(scope->>'revision' IS DISTINCT FROM old_revision,'membership change invalidates previous plan');
 PERFORM assert_true(public.get_ticket_wallet_projections(hg,ARRAY[b],old_revision) IS NULL,'stale plan cannot silently change its contents');
 UPDATE eshop.tickets SET state='used' WHERE id=b;
 PERFORM assert_true(public.resolve_ticket_wallet(hg,src) IS NULL,'used group has no active ticket to add');
END $$;
